100	  // 4. Render preflight results checklist.
101	  function renderPreflightResults(checks) {
102	    if (!checks || !checks.length) {
103	      resultsEl.innerHTML = '';
104	      allChecksPassed = false;
105	      startBtn.disabled = true;
106	      return;
107	    }
108	    allChecksPassed = checks.every(function (c) { return c.pass; });
109	    startBtn.disabled = !allChecksPassed;
110	    if (!startBtn.disabled) startBtn.textContent = 'Start Run';
111	
112	    var html = '<ul class="preflight-list">';
113	    checks.forEach(function (c) {
114	      var cls = c.pass ? 'preflight-pass' : 'preflight-fail';
115	      html += '<li class="preflight-check ' + cls + '">';
116	      html += '<span class="preflight-icon">' + (c.pass ? '✓' : '✗') + '</span>';
117	      html += ' <strong>' + escapeHtml(c.name) + '</strong>: ' + escapeHtml(c.detail);
118	      if (!c.pass && c.fix) {
119	        html += ' <span class="preflight-fix">Fix: <code>' + escapeHtml(c.fix) + '</code></span>';
120	      }
121	      html += '</li>';
122	    });
123	    html += '</ul>';
124	    resultsEl.innerHTML = html;
125	  }
