127	  // 5. Preflight button handler.
128	  preflightBtn.addEventListener('click', function () {
129	    var planPath = planInput.value.trim();
130	    if (!planPath) { window.alert('Please enter a plan path.'); return; }
131	
132	    preflightBtn.disabled = true;
133	    preflightBtn.textContent = 'Running…';
134	    resultsEl.innerHTML = '<p class="text-muted">Running preflight checks…</p>';
135	    allChecksPassed = false;
136	    startBtn.disabled = true;
137	
138	    API.orchestratorStart(planPath, true).then(function (result) {
139	      renderPreflightResults((result && result.checks) ? result.checks : []);
140	    }).catch(function (err) {
141	      resultsEl.innerHTML = '<p class="error-banner">Preflight error: ' +
142	        escapeHtml((err && err.message) ? err.message : String(err)) + '</p>';
143	    }).then(function () {
144	      preflightBtn.disabled = false;
145	      preflightBtn.textContent = 'Run Preflight';
