149	  // 6. Start Run button handler.
150	  startBtn.addEventListener('click', function () {
151	    var planPath = planInput.value.trim();
152	    if (!planPath || !allChecksPassed) return;
153	
154	    startBtn.disabled = true;
155	    startBtn.textContent = 'Starting…';
156	
157	    API.orchestratorStart(planPath, false).then(function (result) {
158	      if (result && result.started) {
159	        var runStatusFilename = result.runStatusFilename || null;
160	        planInput.value = '';
161	        resultsEl.innerHTML =
162	          '<p class="success-banner">✓ Orchestrator launched' +
163	          (result.pid ? ' (PID\u00a0' + result.pid + ')' : '') +
164	          '. Waiting for the run to appear in the queue below…</p>';
165	        allChecksPassed = false;
166	        startBtn.disabled = true;
167	        refreshQueue();
168	
169	        // Poll the run-status tombstone so we can surface fatal early
170	        // failures (e.g. invalid API key) that complete before the first
171	        // queue poll cycle.
172	        if (runStatusFilename) {
173	          var pollCount = 0;
174	          var MAX_STATUS_POLLS = 15; // 2s × 15 = 30s window
175	          var statusPollTimer = setInterval(function () {
176	            pollCount++;
177	            API.orchestratorGetRunStatus(runStatusFilename).then(function (status) {
178	              if (!status) return; // file not yet written — run still in progress
179	              clearInterval(statusPollTimer);
180	              if (status.result === 'ERROR' && status.error) {
181	                resultsEl.innerHTML =
182	                  '<p class="error-banner">Run failed: ' +
183	                  escapeHtml(status.error) + '</p>';
184	              }
185	              // SUCCESS: queue will reflect the project; leave the banner.
186	            }).catch(function () {
187	              // Transient error — keep polling.
188	            });
189	            if (pollCount >= MAX_STATUS_POLLS) {
190	              clearInterval(statusPollTimer);
191	            }
192	          }, 2000);
193	          _orchStatusPollCleanups.push(function () { clearInterval(statusPollTimer); });
194	        }
195	      } else {
196	        // Checks re-evaluated by server — update the checklist.
197	        renderPreflightResults((result && result.checks) ? result.checks : []);
198	      }
199	    }).catch(function (err) {
200	      window.alert('Failed to start: ' + ((err && err.message) ? err.message : String(err)));
201	      startBtn.disabled = !allChecksPassed;
202	      startBtn.textContent = 'Start Run';
203	    }).then(function () {
204	      startBtn.textContent = 'Start Run';
205	    });
206	  });
