216	    var container = document.getElementById('orch-queue-container');
217	    if (!container) return;
218	
219	    API.orchestratorGetQueue().then(function (entries) {
220	      renderQueueTable(container, Array.isArray(entries) ? entries : []);
221	    }).catch(function () {
222	      // Best-effort polling — keep existing content on transient errors.
223	    });
224	  }
