226	  // ---- renderQueueTable helpers (closure-scoped) ----------------------------
227	
228	  /** Removes the success banner from the preflight results area, if present.
229	   *  Error banners are intentionally left intact.
230	   *

231	   *  Closure dependency: `resultsEl` — the #orch-preflight-results element
232	   *  captured by renderOrchestrator() at line 64. */
233	  function _clearSuccessBanner() {
234	    var successBanner = resultsEl.querySelector('.success-banner');
235	    if (successBanner) {
236	      successBanner.remove();
237	    }
238	  }
