240	  /** Builds the queue table HTML string from the entries array.
241	   *  Returns the complete <table>…</table> markup ready to be assigned to
242	   *  container.innerHTML. */
243	  function _buildQueueHtml(entries) {
244	    var html = '<table class="table orch-queue-table"><thead>' +
245	      '<tr><th></th><th>Plan</th><th>Status</th><th>Elapsed</th><th>Progress</th><th>Actions</th></tr>' +
246	      '</thead><tbody>';
247	    entries.forEach(function (entry) {
248	      var id         = entry.id || '';
249	      var status     = entry.effectiveStatus || 'pending';
250	      var planName   = _orchBasename(entry.planPath || '');
251	      var elapsed    = _orchElapsed(entry.startedAt);
252	      var isExpanded = !!expandedIds[id];
253	      var statusBadgeHtml = '<span class="badge badge-' + escapeHtml(status) + '">' +
254	        escapeHtml(_orchStatusLabel(status)) + '</span>';
255	      // Progress cell: badge + text summary + optional log link.
256	      var progressHtml = OrchestratorWidgets.renderProgressBadge(entry.lastAction || null);
257	      if (entry.progress) {
258	        progressHtml += ' <span class="orch-progress-text">' + escapeHtml(entry.progress) + '</span>';
259	      }
260	      if (entry.logFilename && entry.expectedSlug) {
261	        progressHtml += ' <a href="#/projects/' +
262	          encodeURIComponent(entry.expectedSlug) + '/runs/' +
263	          encodeURIComponent(entry.logFilename) + '" class="orch-log-link">View Log →</a>';
264	      } else if (!entry.progress) {
265	        progressHtml += ' <span class="text-muted">Waiting for log…</span>';
266	      }
267	      html += '<tr class="orch-queue-row orch-row-' + escapeHtml(status) + '"' +
268	        ' data-entry-id="' + escapeHtml(id) + '">';
269	      html += '<td class="orch-toggle-cell">' +
270	        '<button type="button" class="orch-row-toggle btn-icon" data-entry-id="' + escapeHtml(id) + '">' +
271	        (isExpanded ? '▼' : '▶') + '</button></td>';
272	      html += '<td class="orch-plan-cell" title="' + escapeHtml(entry.planPath || '') + '">' +
273	        escapeHtml(planName) + '</td>';
274	      html += '<td class="orch-status-cell">' + statusBadgeHtml + '</td>';
275	      html += '<td class="orch-elapsed-cell">' + escapeHtml(elapsed) + '</td>';
276	      html += '<td class="orch-progress-cell">' + progressHtml + '</td>';
277	      html += '<td class="orch-actions-cell" data-actions-for="' + escapeHtml(id) + '"></td>';
278	      html += '</tr>';
279	      if (isExpanded) {
280	        html += '<tr class="orch-log-row" data-entry-id="' + escapeHtml(id) + '">' +
281	          '<td colspan="6">' +
282	          '<div class="orch-log-preview" id="orch-log-' + escapeHtml(id) + '"></div>' +
283	          '</td></tr>';
284	      }
285	    });
286	    html += '</tbody></table>';
287	    return html;
288	  }
289	
290	  /** Injects DOM-based action buttons and toggle listeners into the rendered
291	   *  table. Must be called after container.innerHTML has been set.
292	   *
293	   *  Branch priority (dismissibility-first):
294	   *    1. pending  → Kill button   (process is still running)
295	   *    2. dead     → Dismiss button (process has exited without completing)
296	   *    3. projectExists → View Project link (project ledger is on disk)
297	   *  The dead branch precedes the projectExists branch so that a dead entry
298	   *  that also has a known project slug always renders Dismiss, not View Project.
299	   *
300	   *  Closure dependencies (from renderOrchestrator() scope):
301	   *    `expandedIds`            — tracks which queue rows are expanded; mutated
302	   *                               by toggle clicks to persist state across refreshes.
303	   *    `refreshQueue`           — triggers a fresh API fetch + re-render after
304	   *                               a Kill/Dismiss action or toggle click. */
305	  function _bindQueueActions(container, entries) {
306	    entries.forEach(function (entry) {
307	      var id     = entry.id || '';
308	      var status = entry.effectiveStatus || 'pending';
309	      var cell   = container.querySelector('[data-actions-for="' + id + '"]');
310	      if (!cell) return;
311	
312	      if (status === 'pending') {
313	        cell.appendChild(OrchestratorWidgets.renderKillButton(id, function () {
314	          delete expandedIds[id];
315	          refreshQueue();
316	        }));
317	      } else if (status === 'dead') {
318	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
319	          delete expandedIds[id];
320	          refreshQueue();
321	        }));
322	      } else if (entry.projectExists === true && entry.expectedSlug) {
323	        var link = document.createElement('a');
324	        link.href = '#/projects/' + encodeURIComponent(entry.expectedSlug);
325	        link.className = 'btn btn-sm btn-secondary orch-project-link';
326	        link.textContent = 'View Project';
327	        cell.appendChild(link);
328	      }
329	    });
330	
331	    var toggleBtns = container.querySelectorAll('.orch-row-toggle');
332	    Array.prototype.forEach.call(toggleBtns, function (btn) {
333	      btn.addEventListener('click', function () {
334	        var id = btn.getAttribute('data-entry-id');
335	        if (id) expandedIds[id] = !expandedIds[id];
336	        refreshQueue();
337	      });
338	    });
339	  }
340	
341	  /** Starts log previews for all currently expanded rows and registers their
342	   *  cleanup callbacks in _orchLogPreviewCleanups.
343	   *
344	   *  Closure dependencies (from renderOrchestrator() scope):
345	   *    `expandedIds`              — read to determine which rows are currently
346	   *                                 expanded; only those rows get a live preview.
347	   *    `_orchLogPreviewCleanups`  — the module-level cleanup registry; each
348	   *                                 preview's cleanup callback is pushed here so
349	   *                                 it is cancelled when renderOrchestrator() or
350	   *                                 refreshQueue() next runs. */
351	  function _mountLogPreviews(container, entries) {
352	    entries.forEach(function (entry) {
353	      var id = entry.id || '';
354	      if (!expandedIds[id] || !entry.logFilename || !entry.expectedSlug) return;
355	      var previewEl = document.getElementById('orch-log-' + id);
356	      if (!previewEl) return;
357	      var cleanup = OrchestratorWidgets.renderLogPreview(
358	        previewEl,
359	        entry.expectedSlug,
360	        entry.logFilename
361	      );
362	      _orchLogPreviewCleanups.push(cleanup);
363	    });
364	  }
365	
366	  // ---- renderQueueTable coordinator ----------------------------------------
367	
368	  function renderQueueTable(container, entries) {
369	    // Save viewport scroll position before replacing innerHTML — the document
370	    // viewport is the scrolling context (not the container, which has no
371	    // overflow CSS), so window.scrollY is the correct save/restore target.
372	    var savedScrollY = window.scrollY;
373	
374	    if (!entries.length) {
375	      container.innerHTML = '<p class="text-muted orch-empty-queue">No active runs in the queue.</p>';
376	      return;
377	    }
378	
379	    _clearSuccessBanner();
380	    container.innerHTML = _buildQueueHtml(entries);

381	    _bindQueueActions(container, entries);
382	    _mountLogPreviews(container, entries);
383	
384	    // Restore scroll position after all DOM manipulation is complete.
385	    // Must be the last statement so intermediate DOM mutations do not
386	    // interfere with the restored position.
387	    window.scrollTo(0, savedScrollY);
388	  }
389	
390	  // 8. Kick off the first queue fetch and register the polling interval.
391	  refreshQueue();
392	  Router._setPolling(refreshQueue, 5000);
393	}
