395	// ---------------------------------------------------------------------------
396	// Private helpers
397	// ---------------------------------------------------------------------------
398	
399	/** Returns the final path segment (filename or folder name). */
400	function _orchBasename(path) {
401	  var parts = String(path).replace(/\\/g, '/').split('/');
402	  return parts[parts.length - 1] || path;
403	}
404	
405	/** Human-readable label for an effectiveStatus value. */
406	function _orchStatusLabel(status) {
407	  if (status === 'started') return 'Started';
408	  if (status === 'dead')    return 'Dead';
409	  return 'Pending';
410	}
411	
412	/** Formats elapsed time from an ISO start timestamp. */
413	function _orchElapsed(startedAt) {
414	  if (!startedAt) return '—';
415	  try {
416	    var diff = Date.now() - new Date(startedAt).getTime();
417	    if (isNaN(diff) || diff < 0) return '—';
418	    var secs = Math.round(diff / 1000);
419	    if (secs < 60)  return secs + 's';
420	    var mins = Math.floor(secs / 60);
421	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
422	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
423	  } catch (_) {
424	    return '—';
425	  }
426	}

